INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Moore is a poor plumber who cannot be counted on to do good work.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$In one small town, every filed complaint about a plumber's work was against Moore, despite Moore's relatively small business.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$That sounds damning until we ask for the comparison group. Are there many other plumbers receiving no complaints, or does Moore do nearly all the plumbing in town? If Moore is the only plumber, every plumbing complaint would necessarily name Moore, even if his work is generally good. The distribution of complaints alone does not establish his reliability.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for the missing base rate: how many other plumbers could have received complaints?$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT115-S4-Q21$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Customers without complaints might matter if we knew how many there were, but their *interests* do not explain why Moore received all filed complaints.$batch01$), ($batch01$B$batch01$, $batch01$There may be few or no competing plumbers. If Moore performs almost all the plumbing work, all complaints naming him would be unsurprising and would not establish that his work is unusually poor. The argument needs a meaningful comparison.$batch01$), ($batch01$C$batch01$, $batch01$A small business can still produce enough jobs to support a judgment. The specific gap is the number of other plumbers and jobs available for comparison, not a bare question about whether Moore's business is "too small."$batch01$), ($batch01$D$batch01$, $batch01$Complaints about electricians, carpenters, or other tradespeople would not tell us whether Moore performs plumbing work well.$batch01$), ($batch01$E$batch01$, $batch01$If more dissatisfied Moore customers failed to complain, that would make the known complaints undercount dissatisfaction and could strengthen the criticism. It does not expose why *all filed plumbing complaints* point to Moore.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT115-S4-Q21$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
